llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Fexofenadine, a piperidine carbinol with a phenyl substituent and known P-gp efflux, has absolute oral bioavailability of 33% in humans, demonstrating that this scaffold can exceed the 20% threshold despite transporter and absorption limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Bidisomide, a basic piperidine with a central quaternary carbon bearing phenyl and amide groups, has absolute oral bioavailability of approximately 61% in humans, showing that related piperidine-containing drugs can have good systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Ebastine, a lipophilic piperidine-containing drug, achieves about 40% oral bioavailability in humans, supporting adequate F for a similar lipophilic basic piperidine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Darifenacin, an antimuscarinic with a basic amine and extensive first-pass metabolism, has oral bioavailability of 15-19% in humans, below the threshold; this is the most relevant low-F analogue because of shared antimuscarinic/amine features, but its amide and dihydrobenzofuran moieties reduce transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Terfenadine has <2% absolute oral bioavailability in humans due to extensive first-pass metabolism, but it is a prodrug to fexofenadine and lacks the query's norbornenyl alcohol, so its low-F result transfers poorly.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Loperamide has very low oral bioavailability (0.3%) attributed to P-gp efflux and first-pass metabolism, but its amide/chlorophenyl structure and strong P-gp recognition are not shared by the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction: high (F >=20%). The query is a lipophilic basic tertiary amine with a piperidine-phenyl-carbinol core. The most transferable experimental evidence from fexofenadine (30-33%), bidisomide (43-61%), and ebastine (~40%) supports adequate oral bioavailability. Low-F analogues such as darifenacin, terfenadine, and loperamide are less structurally transferable due to amide/prodrug/P-gp liabilities. Overall, F >=20% is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the query molecule itself in the supplied evidence.",
    "All retrieved analogues have low Morgan similarity (<0.30), limiting quantitative transfer.",
    "Conflicting loperamide bioavailability values (0.3% vs ~40%) introduce uncertainty.",
    "First-pass metabolism extent for the norbornenyl-phenyl-carbinol core is not directly measured in the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

